const body = $('1. Webhook Input').item.json.body || {};
const query = (body.query || '').trim();
const sessionId = body.sessionId || 'default_session';
const history = Array.isArray(body.history) ? body.history.slice(-4) : []; // keep last 2 turns (4 entries)
const receivedAt = Date.now();

if (!query) {
  return [{
    json: {
      error: 'Missing query parameter in request body.',
      isValid: false,
      receivedAt,
      sessionId
    }
  }];
}

// Harbor & Pine Living system prompt — concise, grounded, voice-friendly
const systemInstruction = `You are a Harbor & Pine Living customer-support assistant speaking over the phone.

PRINCIPLES:
1. The retrieved Harbor & Pine context is your ONLY source of truth.
2. Answer the customer's question ONLY using information supported by the retrieved context.
3. Do NOT use general world knowledge to fill missing information.
4. Do NOT invent policies, prices, delivery times, product specifications, refund guarantees, exceptions, or procedures.
5. If the retrieved context does not contain enough information to answer, clearly say the information could not be confirmed and offer human support.
6. Follow the limitations in the retrieved content. If it says a human must review something, do not claim the action was completed.
7. Do not claim that a refund, cancellation, address change, order edit, payment, privacy request, replacement, or policy exception was completed when the context says you cannot perform it.

VOICE RESPONSE STYLE:
- Keep responses concise: 1 to 3 sentences, 40 to 100 words.
- Give the direct answer first.
- Use natural conversational English.
- No Markdown, no bullet points, no numbered lists, no headings, no tables.
- Do not mention Qdrant, embeddings, RAG, chunks, or internal architecture.
- If the answer is unsupported, use this fallback: "I could not confirm that from the approved Harbor & Pine information, so I do not want to guess. I can help you request human support."`;

return [{
  json: {
    query,
    sessionId,
    history,
    systemInstruction,
    receivedAt,
    isValid: true
  }
}];

const scaffold = $('2b. Prompt Scaffold').first().json;
const retrievalTime = Date.now();
const ragLatencyMs = retrievalTime - scaffold.receivedAt;

if (!scaffold.isValid) {
  return [{ json: { ...scaffold, ragLatencyMs } }];
}

// Extract Qdrant search results using CURRENT chunk payload schema:
// { id, type, title, content, source, source_type }
const qdrantResults = $('2a2. Qdrant Vector Search').item.json.result || [];

const retrievedChunks = qdrantResults.map(hit => ({
  score: hit.score,
  id: hit.payload?.id || 'Unknown',
  type: hit.payload?.type || 'unknown',
  title: hit.payload?.title || hit.payload?.section || '',
  content: hit.payload?.content || hit.payload?.text || '',
  source: hit.payload?.source || 'harbor_pine_kb.pdf',
  source_type: hit.payload?.source_type || 'pdf'
})).filter(c => c.content.length > 0);

// Format context for LLM: [ID] Title\nContent\n\n
// Context cap: keep retrieved context under ~3000 chars to stay within token budget
let combinedContext = '';
for (const chunk of retrievedChunks) {
  const block = `[${chunk.id}] ${chunk.title}\n${chunk.content}`;
  if ((combinedContext + block).length <= 3000) {
    combinedContext += block + '\n\n';
  }
}

if (!combinedContext.trim()) {
  combinedContext = 'No relevant Harbor & Pine information was found for this query.';
}

// Format conversation history (last 2 turns max)
let conversationHistoryText = '';
if (scaffold.history && scaffold.history.length > 0) {
  conversationHistoryText = 'Recent conversation:\n' +
    scaffold.history.map(t => `${t.role}: ${t.content}`).join('\n') + '\n\n';
}

const fullPrompt = `${scaffold.systemInstruction}\n\n${conversationHistoryText}Retrieved Harbor & Pine information:\n${combinedContext.trim()}\n\nCustomer question: ${scaffold.query}\n\nGenerate the customer-facing answer.`;

return [{
  json: {
    query: scaffold.query,
    sessionId: scaffold.sessionId,
    fullPrompt,
    retrievedChunks,
    retrievedChunksCount: retrievedChunks.length,
    receivedAt: scaffold.receivedAt,
    ragLatencyMs
  }
}];

const responseJson = $json;
const promptData = $('4. Assemble Safe LLM Prompt').first().json;
const llmCompletedAt = Date.now();
const llmLatencyMs = llmCompletedAt - (promptData.receivedAt + promptData.ragLatencyMs);

const FALLBACK = 'I could not confirm that from the approved Harbor & Pine information, so I do not want to guess. I can help you request human support.';

let fullText = '';
if (responseJson.candidates && responseJson.candidates[0]?.content?.parts) {
  fullText = responseJson.candidates[0].content.parts.map(p => p.text || '').join('');
} else if (responseJson.text) {
  fullText = responseJson.text;
}

if (!fullText.trim()) {
  fullText = FALLBACK;
}

// Sentence & clause buffering: isolate first clean sentence for low-latency TTS
const sentences = fullText.split(/(?<=[.?!])\s+/).filter(Boolean);
const firstSentence = sentences.length > 0 ? sentences[0] : fullText;
const remainingText = sentences.slice(1).join(' ');

return [{
  json: {
    ...promptData,
    fullText,
    ttsInputText: firstSentence,
    remainingText,
    llmCompletedAt,
    llmLatencyMs
  }
}];
